package ui;

import java.util.Optional;
import javafx.scene.control.Alert;
import javafx.scene.control.Button;
import javafx.scene.control.ButtonBar;
import javafx.scene.control.ButtonType;
import javafx.scene.control.DialogPane;
import javafx.stage.Window;

/** Questions asked before an action that would throw away the marker's work. */
final class Confirmations {

    private static final ButtonType IMPORT_ANYWAY = new ButtonType("Import anyway", ButtonBar.ButtonData.OK_DONE);
    private static final ButtonType KEEP_RESULTS = new ButtonType("Keep results", ButtonBar.ButtonData.CANCEL_CLOSE);
    private static final ButtonType STOP_AND_CLOSE = new ButtonType("Stop and close", ButtonBar.ButtonData.OK_DONE);
    private static final ButtonType KEEP_GRADING = new ButtonType("Keep grading", ButtonBar.ButtonData.CANCEL_CLOSE);

    private Confirmations() {
    }

    /** Before importing another submissions folder over finished results. */
    static Alert replaceResults(long gradedCount) {
        return create("Replace graded results?",
                "Importing another folder clears the results of the " + gradedCount + " graded "
                        + (gradedCount == 1 ? "student." : "students."),
                "Their PDF reports stay in the grading-reports folder.", IMPORT_ANYWAY, KEEP_RESULTS);
    }

    /** Before closing the window while grading runs. */
    static Alert stopGrading() {
        return create("Grading is running", "Stop grading and close the window?",
                "Marks from this run are not kept.", STOP_AND_CLOSE, KEEP_GRADING);
    }

    /** Shows the question and says whether the marker chose to go ahead. */
    static boolean ask(Alert alert, Window owner) {
        alert.initOwner(owner);
        Optional<ButtonType> answer = alert.showAndWait();
        return answer.map(button -> button.getButtonData() == ButtonBar.ButtonData.OK_DONE).orElse(false);
    }

    // Going ahead is the secondary choice; keeping the work is the default, so Enter is always safe.
    private static Alert create(String title, String header, String content, ButtonType goAhead, ButtonType keep) {
        Alert alert = new Alert(Alert.AlertType.WARNING, content, goAhead, keep);
        alert.setTitle(title);
        alert.setHeaderText(header);
        DialogPane pane = alert.getDialogPane();
        // dialogs open in their own window, so they need the application's stylesheet explicitly
        pane.getStylesheets().add(Confirmations.class.getResource("/ui/styles.css").toExternalForm());
        Button goAheadButton = (Button) pane.lookupButton(goAhead);
        Button keepButton = (Button) pane.lookupButton(keep);
        goAheadButton.getStyleClass().add("dialog-secondary-button");
        keepButton.getStyleClass().add("dialog-primary-button");
        goAheadButton.setDefaultButton(false);
        keepButton.setDefaultButton(true);
        return alert;
    }
}
